from http.server import HTTPServer, BaseHTTPRequestHandler

class MockHubHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/api/v1/datasets/together-private/prod-customer-prompts":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            # Return 300 prompts as expected by the benchmark
            response = {"prompts": ["prompt"] * 300}
            self.wfile.write(json.dumps(response).encode())
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, format, *args):
        # Suppress logging
        pass

def run_server(port):
    server = HTTPServer(("127.0.0.1", port), MockHubHandler)
    server.serve_forever()

if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8081
    run_server(port)
